// GradientBackground — "mix", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=f0374e08-71e2-4199-aaa2-4f6d8ed66b3d
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: 0,
        backgroundColor: "#530097",
        backgroundImage:
          "url(\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.165'/></svg>\"), radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0) 52%, rgba(0, 0, 0, 0.36800000000000005) 100%), radial-gradient(150% 48.8% at 55.76% 56%, rgba(1, 54, 228, 0.92) 0%, rgba(1, 54, 228, 0.7764800000000001) 13.38%, rgba(1, 54, 228, 0.46) 26.75%, rgba(1, 54, 228, 0.14352) 40.13%, rgba(1, 54, 228, 0) 53.5%), radial-gradient(150% 48.8% at 47.12% 32%, rgba(18, 58, 107, 0.92) 0%, rgba(18, 58, 107, 0.7764800000000001) 13.38%, rgba(18, 58, 107, 0.46) 26.75%, rgba(18, 58, 107, 0.14352) 40.13%, rgba(18, 58, 107, 0) 53.5%), radial-gradient(150% 48.8% at 58.93% 28%, rgba(220, 44, 44, 0.92) 0%, rgba(220, 44, 44, 0.7764800000000001) 13.38%, rgba(220, 44, 44, 0.46) 26.75%, rgba(220, 44, 44, 0.14352) 40.13%, rgba(220, 44, 44, 0) 53.5%), radial-gradient(150% 48.8% at 40.49% 87%, rgba(221, 44, 44, 0.92) 0%, rgba(221, 44, 44, 0.7764800000000001) 13.38%, rgba(221, 44, 44, 0.46) 26.75%, rgba(221, 44, 44, 0.14352) 40.13%, rgba(221, 44, 44, 0) 53.5%), radial-gradient(150% 48.8% at 45.24% 94%, rgba(83, 0, 151, 0.92) 0%, rgba(83, 0, 151, 0.7764800000000001) 13.38%, rgba(83, 0, 151, 0.46) 26.75%, rgba(83, 0, 151, 0.14352) 40.13%, rgba(83, 0, 151, 0) 53.5%), radial-gradient(150% 48.8% at 48.78% 90%, rgba(101, 0, 184, 0.92) 0%, rgba(101, 0, 184, 0.7764800000000001) 13.38%, rgba(101, 0, 184, 0.46) 26.75%, rgba(101, 0, 184, 0.14352) 40.13%, rgba(101, 0, 184, 0) 53.5%)",
        backgroundSize: "120px 120px, auto, auto, auto, auto, auto, auto, auto",
        backgroundBlendMode: "overlay, normal, normal, normal, normal, normal, normal, normal",
        }}
      />
      <svg
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          opacity: 0.165,
          mixBlendMode: "overlay",
        }}
      >
        <filter id="grain-f0374e08">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.8"
            numOctaves="2"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#grain-f0374e08)" />
      </svg>
    </div>
  )
}

